import type { User } from "./user.ts";
export type OptimizationStatus = "optimizing" | "optimized" | "error";
export interface Publish {
    deploymentTime: number;
    optimizationStatus: OptimizationStatus;
    url: string;
    currentPageUrl: string;
}
export interface PublishInfo {
    production: Publish | null;
    staging: Publish | null;
}
export type DeploymentStatus = "pending" | "optimizing" | "ready" | "failed";
export type DeploymentFailureStage = "publish" | "optimization";
export type DeploymentIssueSeverity = "warning" | "error";
export interface DeploymentIssue {
    severity: DeploymentIssueSeverity;
    message: string;
    nodeId?: string;
}
interface DeploymentBase {
    id: string;
    /** The user who created the deployment, or `null` if that user is no longer available. */
    deployedBy: User | null;
    createdAt: string;
    updatedAt: string;
    versionUrl?: string;
}
export type Deployment = (DeploymentBase & {
    status: "pending" | "optimizing" | "ready";
    failureStage?: never;
}) | (DeploymentBase & {
    status: "failed";
    failureStage: DeploymentFailureStage;
});
export interface ListDeploymentsPage {
    deployments: Deployment[];
    cursor?: string;
    hasNextPage: boolean;
}
export type HostnameType = "default" | "custom" | "version" | "branch";
export interface Hostname {
    hostname: string;
    type: HostnameType;
    isPrimary: boolean;
    isPublished: boolean;
    deploymentId: string;
}
export interface PublishResult {
    deployment: Deployment;
    hostnames: Hostname[];
}
export {};
